<template>
  <div class="admin-page"><header class="admin-topbar"><RouterLink class="wordmark" to="/">TECHIDEATE <span>26</span></RouterLink><span class="admin-label">CONTENT CONTROL / SUPER ADMIN</span><RouterLink class="back-link" to="/">EXIT ↗</RouterLink></header><main class="admin-shell"><aside class="admin-sidebar"><p class="eyebrow">CONTROL ROOM</p><button v-for="item in sections" :key="item.id" :class="{ active: section === item.id }" @click="section = item.id">{{ item.label }}</button><div class="admin-user"><span class="status-dot"></span><div><strong>Super Admin</strong><small>All access enabled</small></div></div></aside><section class="admin-content"><div class="admin-heading"><div><p class="eyebrow">LIVE WORKSPACE / {{ section.toUpperCase() }}</p><h1>{{ currentTitle }}</h1></div><button class="button button-lime" @click="showComposer = true">+ ADD {{ section === 'events' ? 'EVENT' : 'PROMOTION' }}</button></div><div v-if="section === 'overview'" class="stat-grid"><article v-for="stat in stats" :key="stat.label" class="stat-card"><span>{{ stat.label }}</span><strong>{{ stat.value }}</strong><small>{{ stat.note }}</small></article></div><div v-if="section === 'clubs'" class="admin-table"><div class="table-row table-head"><span>CLUB</span><span>OWNER ACCESS</span><span>STATUS</span><span>ACTION</span></div><div v-for="club in store.state.clubs" :key="club.id" class="table-row"><strong>{{ club.name }}</strong><span>club-{{ club.id }}@techideate.in</span><span class="status approved">APPROVED</span><button @click="selected = club">EDIT ↗</button></div></div><div v-if="section === 'events'" class="admin-table"><div class="table-row table-head"><span>EVENT</span><span>CLUB</span><span>DAY / TIME</span><span>STATUS</span></div><div v-for="event in store.state.events" :key="event.id" class="table-row"><strong>{{ event.title }}</strong><span>{{ store.getClub(event.clubId)?.shortName }}</span><span>DAY {{ event.day }} · {{ event.time }}</span><span class="status approved">PUBLISHED</span></div></div><div v-if="section === 'promotions'" class="promotion-admin-grid"><article v-for="promotion in store.state.promotions" :key="promotion.id" class="promotion-admin" :style="{ '--club-accent': promotion.accent }"><span class="eyebrow">DISPLAY 0{{ promotion.displayOrder }}</span><h2>{{ promotion.title }}</h2><p>{{ store.getClub(promotion.clubId)?.name }}</p><button class="status approved" @click="togglePromotion(promotion)">{{ promotion.status === 'approved' ? 'PUBLISHED' : 'PUBLISH' }}</button></article></div><div v-if="section === 'team'" class="team-admin-list"><div v-for="member in store.state.team" :key="member.name" class="team-admin-row"><div class="avatar small">{{ member.initials }}</div><strong>{{ member.name }}</strong><span>{{ member.role }}</span><button>EDIT ↗</button></div></div></section></main><div v-if="showComposer" class="modal-backdrop" @click.self="showComposer = false"><form class="modal" @submit.prevent="createEvent"><button type="button" class="modal-close" @click="showComposer = false">×</button><p class="eyebrow">NEW EVENT / DRAFT</p><h2>ADD TO THE RUN OF SHOW.</h2><label>Event name<input v-model="draft.title" required placeholder="e.g. Future Systems Lab"></label><label>Club<select v-model="draft.clubId"><option v-for="club in store.state.clubs" :key="club.id" :value="club.id">{{ club.name }}</option></select></label><div class="form-grid"><label>Day<input v-model.number="draft.day" type="number" min="1" max="3"></label><label>Time<input v-model="draft.time" required placeholder="10:00 - 12:00"></label></div><label>Description<textarea v-model="draft.description" required rows="4"></textarea></label><button class="button button-lime">SAVE EVENT</button></form></div></div>
</template>
<script setup>
import { computed, reactive, ref } from 'vue'
import { useContentStore } from '../data/contentStore'
const store = useContentStore(); const section = ref('overview'); const selected = ref(null); const showComposer = ref(false)
const sections = [{ id: 'overview', label: 'OVERVIEW' }, { id: 'clubs', label: 'CLUBS' }, { id: 'events', label: 'EVENTS' }, { id: 'promotions', label: 'PROMOTIONS' }, { id: 'team', label: 'TEAM' }]
const draft = reactive({ title: '', clubId: store.state.clubs[0].id, day: 1, time: '', description: '', category: 'TECH' })
const currentTitle = computed(() => sections.find((item) => item.id === section.value)?.label || 'OVERVIEW')
const stats = computed(() => [{ label: 'LIVE CLUBS', value: store.state.clubs.length, note: 'approved partners' }, { label: 'EVENTS', value: store.state.events.length, note: 'across 3 days' }, { label: 'PROMOTIONS', value: store.approvedPromotions().length, note: 'on public screens' }, { label: 'TEAM', value: store.state.team.length, note: 'festival leads' }])
function createEvent() { store.addEvent({ ...draft }); showComposer.value = false; Object.assign(draft, { title: '', time: '', description: '' }); section.value = 'events' }
function togglePromotion(promotion) { store.updatePromotion(promotion.id, { status: promotion.status === 'approved' ? 'draft' : 'approved' }) }
</script>
